theorem.raw:
\label{NoDiffAsCommutator_Theorem}
	There are no finite-dimensional operators $\hat{A}$ and $\hat{B}$ such that 
	\begin{align}\label{NoDiffAsCommutator_Eq1}
		\commut{ f(\hat{A}), \hat{B} } =  f'(\hat{A})
	\end{align}
	for any ``good'' function $f(z)$.

lemma.raw:
\label{NonHermitian_Lemma1}
	Assume that $\hat{x}$, $\hat{p}$, and $\hat{H}$ are bounded. If $\sigma(\hat{H}^{\dagger}) \cap \sigma(\hat{H}) = \emptyset$ and
	\begin{align}
		& im ( \hat{H}^{\dagger} \hat{x} - \hat{x} \hat{H} ) = \hbar \hat{p}, \label{First_OperEq_for_NonHer_FreeHamiltonian} \\
		& \hat{H}^{\dagger} \hat{p} = \hat{p} \hat{H}, \label{Second_OperEq_for_NonHer_FreeHamiltonian}
	\end{align}
	then $\hat{p} = \hat{x} = 0$. Here, $\sigma(\hat{A})$ denotes the spectrum of an operator $\hat{A}$.

proof.raw:
Let $\ket{E_n}$ denote a joint eigenvector of $\hat{H}$ and $\hat{p}$ such that $\hat{H} \ket{E_n} = E_n \ket{E_n}$ and $\hat{p} \ket{E_n} = p_n \ket{E_n}$. Assuming that $i \commut{ \hat{H}, \hat{x} } = \hat{p}$, one obtains 
	\begin{align}
		i \bra{E_n} \commut{ \hat{H}, \hat{x} } \ket{E_m} = i (E_n - E_m) \bra{E_n} \hat{x} \ket{E_m} = p_m \langle E_n \ket{E_m}, 
	\end{align}
	$\forall n,m$.
	The special case of this identity, when $n=m$, reads $p_m = 0$, $\forall m$. This contradicts the assumption that $\hat{p}$ is a non-zero matrix.

Let a function of an operator be defined as  (see, e.g., Ref. \cite{Nazaikinskii1992})
	\begin{align}
		f(\hat{A}) \coloneqq \int g(k) e^{ik\hat{A}} dk, \quad f'(\hat{A}) \coloneqq \int ik g(k) e^{ik\hat{A}} dk, \notag
	\end{align}
	where $g(k)$ is the Fourier transform of a function $f(z)$. The correctness of Eq. (\ref{NoDiffAsCommutator_Eq1}) implies 
	\begin{align}
		\commut{ e^{ik\hat{A}}, \hat{B} } = ik e^{ik\hat{A}}.
	\end{align}
	Differentiating the last identity with respect to $k$ and setting $k=0$, we reach the contradiction $\commut{ \hat{A}, \hat{B} } = 1$.

First, we employ the Rosenblum theorem \cite{Rosenblum1956} (see Theorem 9.3 in Ref. \cite{Bhatia1997}) to Eq. (\ref{First_OperEq_for_NonHer_FreeHamiltonian}) and then employ Eq. (\ref{Second_OperEq_for_NonHer_FreeHamiltonian}) to show 
	\begin{align}
		im\hat{x} =& \frac{\hbar}{2\pi i} \oint_{\Gamma} d\xi ( \hat{H}^{\dagger} - \xi )^{-1} \hat{p} ( \hat{H} - \xi )^{-1} \notag\\
			=&  \frac{\hbar}{2\pi i} \hat{p} \oint_{\Gamma} d\xi ( \hat{H} - \xi )^{-2}  = 0,
	\end{align}
	where $\Gamma$ denotes a union of closed contours in the complex plane with total winding numbers $1$ around $\sigma(\hat{H}^{\dagger})$ and $0$ around $\sigma(\hat{H})$.

Suppose $\hat{p} \neq 0$. According to Lyapunov stability theory \cite{Lyapunov1992}, the second assumption implies that $\Im(E_n) \leqslant 0$, $\forall n\in I$. Lemma \ref{NonHermitian_Lemma1} guarantees that $\hat{H}$ has at least a single real eigenvalue. Introduce $R \coloneqq \{ n \in I \, | \, \Im(E_n) = 0 \} \neq \emptyset$ -- the set of the real eigenvalues' indices. 
	``Sandwiching'' Eqs. (\ref{First_OperEq_for_NonHer_FreeHamiltonian}) and (\ref{Second_OperEq_for_NonHer_FreeHamiltonian}) leads to
	\begin{align}
		& im ( E_k^* - E_l ) \bra{E_k} \hat{x} \ket{E_l} = \hbar \bra{E_k} \hat{p} \ket{E_l}, \label{NonHermTh1_Eq1}\\
		& ( E_k^* - E_l ) \bra{E_k} \hat{p} \ket{E_l} = 0, \qquad \forall k,l \in I. \label{NonHermTh1_Eq2}
	\end{align}
	According to Eq. (\ref{NonHermTh1_Eq2}), $\bra{E_k} \hat{p} \ket{E_l}$ may be non-zero only for $(k,l) \in Q \coloneqq \{ (k,l) \in R \times R \, | \, E_k = E_l \}$. However, Eq. (\ref{NonHermTh1_Eq1}) enforces $\bra{E_k} \hat{p} \ket{E_l} = 0$, $\forall (k,l) \in Q$. Therefore, we reach the contradiction $\hat{p} = 0$.

